import java.io.*;
import java.net.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;

/** Persistent TCP gateway used by Nokia clients; web/admin remain on HTTP. */
final class TcpGameServer implements AutoCloseable {
 static final int MAGIC=0x474e5954,MAX_BODY=131072;
 final GunnyServer server;final java.util.Set<Socket> sockets=ConcurrentHashMap.newKeySet();final ServerSocket listener;final int maxClients;final ExecutorService clients=Executors.newCachedThreadPool();final AtomicInteger active=new AtomicInteger();volatile boolean closed;Thread acceptor;
 TcpGameServer(String bind,int port,GunnyServer server,int maxClients)throws IOException {this.server=server;this.maxClients=Math.max(1,maxClients);listener=new ServerSocket();listener.setReuseAddress(true);listener.bind(new InetSocketAddress(bind,port),64);acceptor=new Thread(this::accept,"gunny-tcp-accept");acceptor.start();}
 int port(){return listener.getLocalPort();}
 void accept(){while(!closed)try{Socket socket=listener.accept();if(active.incrementAndGet()>maxClients){active.decrementAndGet();socket.close();continue;}socket.setTcpNoDelay(true);socket.setKeepAlive(true);socket.setSoTimeout(90000);sockets.add(socket);clients.execute(()->serve(socket));}catch(IOException e){if(!closed)System.err.println("TCP accept failed: "+e.getMessage());}}
 void serve(Socket socket){String ip=socket.getInetAddress().getHostAddress();try(socket;DataInputStream in=new DataInputStream(new BufferedInputStream(socket.getInputStream()));DataOutputStream out=new DataOutputStream(new BufferedOutputStream(socket.getOutputStream()))){while(!closed){int magic;try{magic=in.readInt();}catch(EOFException end){break;}if(magic!=MAGIC)throw new IOException("Bad TCP protocol");int kind=in.readUnsignedByte(),flags=in.readInt();String token=in.readUTF();int[] kit={in.readUnsignedByte(),in.readUnsignedByte(),in.readUnsignedByte()};int length=in.readInt();if(length<0||length>MAX_BODY)throw new IOException("Bad TCP frame");byte[] body=in.readNBytes(length);if(body.length!=length)throw new EOFException();byte[] response;int status=200;if(kind==0)response=GunnyServer.capabilities(server.admin.enabled,true).getBytes(java.nio.charset.StandardCharsets.UTF_8);else if(kind==1){TcpExchange exchange=new TcpExchange(socket,body);headers(exchange.request,flags,kit);if(!token.isEmpty())exchange.request.set("Authorization","Bearer "+token);server.api(exchange);status=exchange.status;response=exchange.output.toByteArray();}else if(kind==2){try{response=server.events.waitFor(token,body);}catch(SecurityException e){status=401;response=new byte[0];}catch(Exception e){status=503;response=new byte[0];}}else{status=400;response=new byte[0];}out.writeInt(status);out.writeInt(response.length);out.write(response);out.flush();}}catch(Exception e){if(!closed&&!(e instanceof EOFException)&&!(e instanceof SocketTimeoutException))System.err.println("TCP client "+ip+" closed: "+e.getClass().getSimpleName());}finally{sockets.remove(socket);active.decrementAndGet();}}
 static void headers(com.sun.net.httpserver.Headers h,int f,int[] kit){if((f&65536)!=0)h.set("X-Gunny-Rules","770");if((f&1)!=0)h.set("X-Gunny-Admin","1");if((f&2)!=0)h.set("X-Gunny-ItemFx","1");if((f&4)!=0)h.set("X-Gunny-Bag","1");if((f&8)!=0)h.set("X-Gunny-Equipment","1");if((f&16)!=0)h.set("X-Gunny-Arsenal","2");if((f&32)!=0)h.set("X-Gunny-Cards","1");if((f&64)!=0){h.set("X-Gunny-Items","2");h.set("X-Gunny-Kit",kit[0]+","+kit[1]+","+kit[2]);}if((f&128)!=0)h.set("X-Gunny-RoomFix","1");if((f&256)!=0)h.set("X-Gunny-Wait","1");if((f&512)!=0)h.set("X-Gunny-Match","1");if((f&1024)!=0)h.set("X-Gunny-Social","1");if((f&2048)!=0)h.set("X-Gunny-Chunks","1");if((f&4096)!=0)h.set("X-Gunny-Replay","1");if((f&8192)!=0)h.set("X-Gunny-Client",(f&16384)!=0?"3":"2");if((f&32768)!=0)h.set("X-Gunny-Features","departures");}
 public void close(){closed=true;try{listener.close();}catch(Exception ignored){}for(Socket socket:sockets)try{socket.close();}catch(Exception ignored){}clients.shutdownNow();}
}
